namespace StarlightSyndicateDemo;
public static class StageATests
{
 public static void Run(){int checks=0;void Check(bool value,string reason){checks++;if(!value)throw new Exception("Stage A: "+reason);}
 var dir=Path.Combine(Path.GetTempPath(),"starlight-stage-a-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);
 try{
 var station=Stations44.Stations.First(s=>s.Services.Contains(7)&&s.Services.Contains(14)&&s.Services.Contains(15));var w=new DemoWorld();w.NewExploration43(int.Parse(station.System[7..]));w.StationId=station.Id;w.Screen=ViewMode.Station;w.Grid=station.Id;w.WalletFunds=1000000000000.01m;w.Skills.Grant(SkillCatalog.All.Select(s=>new SkillRequirement(s.Id,5)));w.SyncSkills();
 w.Hangar["miner"]=1000000000000m;w.ChangeStack("miner",true,-1);Check(w.StackCount("miner",true)==999999999999m,"large integer inventory subtraction");w.Hangar["miner"]=0;
 Check(w.OwnedStacks().All(a=>a.Location.World==Spatial43.WorldId&&a.Location.Owner=="player"),"typed ownership and world location");
 Check(w.JumpDistance(station.Id,station.System)==0,"station/system distance");var offer=w.Offers("ammo",station.Id,false).First();decimal balance=w.Balance;w.SubmitMarket("ammo",station.Id,true,2,offer.Price,0,true);Check(w.Balance==balance-2*offer.Price&&w.ItemCount("ammo",true)==2,"imported purchase and exact wallet");
 int count=w.MarketOrders.Count;w.EnsureLocationMarket(station.Id);Check(w.MarketOrders.Count==count,"no reseeding");balance=w.Balance;w.SubmitMarket("ammo",station.Id,true,100000,offer.Price,0,true);Check(w.Balance==balance&&w.ItemCount("ammo",true)==2,"insufficient supply atomic");
 w.SubmitMarket("ammo",station.Id,true,2,.01m,1,true);var order=w.MarketOrders.Single(o=>o.Player);w.CancelMarketOrder(order.Id);Check(!w.MarketOrders.Any(o=>o.Id==order.Id),"cancel escrow");
 Check(w.BuyBlueprint("miner")=="","imported blueprint");var bp=w.Industry.Blueprints.Single();foreach(var input in IndustryCatalog37.Recipes["miner"].Minerals)w.Hangar[input.Key]=100000;
 string install=w.InstallIndustry(bp.Id,IndustryActivity.Manufacturing);Check(install=="","install imported job: "+install);var job=w.Industry.Jobs.Single();DateTime at=w.Now;w.SimulationPaused=true;w.Update(10);Check(w.Now==at&&job.State=="Active","pause clock");w.SimulationPaused=false;Check(w.WaitDocked(job.Seconds/3600+.001)&&job.State=="Ready","docked wait industry");Check(w.DeliverIndustry(job.Id)==""&&w.ItemCount("miner",true)==1,"deliver local output");Check(w.DeliverIndustry(job.Id)!=""&&w.ItemCount("miner",true)==1,"idempotent delivery");
 w.SimulationPaused=true;w.Save();var loaded=new DemoWorld();Check(loaded.Load(w.ActiveSavePath43),"load Stage A");Check(loaded.Now==w.Now&&loaded.SimulationPaused&&loaded.Balance==w.Balance&&loaded.SeededMarkets.SetEquals(w.SeededMarkets),"clock wallet markets roundtrip");Check(loaded.Player.InstanceId==w.Player.InstanceId,"active ship identity roundtrip");Check(loaded.Industry.Jobs.Single().State=="Delivered"&&loaded.ItemCount("miner",true)==1,"job roundtrip");
 var cloneStations=Stations44.Stations.Where(s=>(s.Services.Contains(10)||s.Services.Contains(24))&&w.LegalCloneDestination(s.Id)).Take(2).ToArray();w.StationId=cloneStations[0].Id;w.SystemId=cloneStations[0].System;Check(w.InstallJumpClone(),"imported clone install");var clone=w.JumpClones.Single();w.StationId=cloneStations[1].Id;w.SystemId=cloneStations[1].System;w.CargoItems["miner"]=1;var ship=w.Player;Check(w.JumpToClone(clone.Id)&&w.StationId==cloneStations[0].Id,"clone station destination");Check(w.ParkedShips.Single().System==cloneStations[1].Id&&ReferenceEquals(w.ParkedShips.Single().Ship,ship)&&w.ParkedShips.Single().Cargo["miner"]==1,"ship cargo remain at origin");

 // Actual imported capital transit uses source positions and legal destinations.
 w.StationId=station.Id;w.SystemId=station.System;w.Screen=ViewMode.Station;w.Commander.Capsule=false;w.Player.CapsuleD=false;w.Player.SetCombatHull(FleetCatalog.Source("Rorqual").Id);w.SyncSkills();w.Player.Cap=w.Player.MaxCap;w.Hangar["sp_ozone"]=10000;w.CargoItems["jump_fuel"]=60000;var destination=w.BeaconDestinations().First();Check(w.ContractJumpBeacon(destination.Id,"IndustrialCyno"),"imported beacon contract");int fuel=w.JumpFuelRequired(destination.Id);decimal held=w.StackCount("jump_fuel",false);w.Undock();Check(w.JumpToBeacon(destination.Id)&&w.SystemId==destination.Id&&w.StackCount("jump_fuel",false)==held-fuel,"imported capital fuel and transit");
 w.Screen=ViewMode.Station;w.SystemId=station.System;w.StationId=station.Id;w.Player=new Ship();w.SyncSkills();
 // Imported research/copy and native hull manufacturing.
 w.StationId=station.Id;w.SystemId=station.System;w.Screen=ViewMode.Station;w.SimulationPaused=false;
 Check(w.InstallIndustry(bp.Id,IndustryActivity.MaterialResearch,target:2)=="","imported ME research");var research=w.Industry.Jobs.Last();w.WaitDocked(research.Seconds/3600+.001);Check(w.DeliverIndustry(research.Id)==""&&bp.ME==2,"imported research delivery");
 Check(w.InstallIndustry(bp.Id,IndustryActivity.Copying,runs:2,copies:1)=="","imported copying");var copying=w.Industry.Jobs.Last();w.WaitDocked(copying.Seconds/3600+.001);w.DeliverIndustry(copying.Id);Check(w.Industry.Blueprints.Any(b=>!b.Original&&b.Runs==2&&b.ME==2),"finite copy inheritance");
 string hull=FleetCatalog.Source("Tristan").Id;Check(w.BuyBlueprint(hull)=="","native hull blueprint");var hullBp=w.Industry.Blueprints.Last();var inputs=IndustryCatalog37.Materials(IndustryCatalog37.Recipes[hull],true,1,0,1m);foreach(var input in inputs)w.Hangar[input.Key]=input.Value;
 Check(w.InstallIndustry(hullBp.Id,IndustryActivity.Manufacturing,native:true)=="","native hull installation");var hullJob=w.Industry.Jobs.Last();w.WaitDocked(hullJob.Seconds/3600+.001);Check(w.DeliverIndustry(hullJob.Id)==""&&w.StackCount(hull,true)==1,"native hull exact output");Check(w.AssembleIndustryHull(hull)&&w.Player.CombatHull==hull,"native hull assembly and boarding");
 // Typed standings and imported storyline counter.
 var contact=w.WorldAgents44.First(a=>a.Level==1&&a.Division==AgentDivision38.Distribution);for(int n=0;n<16;n++){w.StationId=contact.Station;w.SystemId=w.LocationSystem(contact.Station);Check(w.RequestMission38(contact.Id)=="","qualifying mission offer");var mission=w.AgentsState.Missions.Last();Check(w.AcceptMission38(mission.Id)=="","mission acceptance");w.StationId=mission.Destination;w.SystemId=w.LocationSystem(mission.Destination);mission.Hangars[mission.Destination]=mission.Spec.Volume;Check(w.CompleteMission38(mission.Id)=="","mission completion");}
 var storyline=w.AgentsState.Missions.Single(m=>m.Storyline);w.StationId=storyline.Pickup;w.SystemId=w.LocationSystem(storyline.Pickup);Check(w.AcceptMission38(storyline.Id)=="","imported storyline acceptance");storyline.Hangars[storyline.Destination]=storyline.Spec.Volume;Check(w.CompleteMission38(storyline.Id)==""&&w.RawStanding38(storyline.Contact.Faction)>0,"typed storyline faction reward");
 w.Screen=ViewMode.Space;w.StationId="";w.Targets.Clear();string localFaction=w.StationFaction;w.AgentsState.Standings[localFaction]=-10;w.UpdateStandingNavy38();Check(w.Targets.Count(t=>t.Id.StartsWith("navy:"))==2,"imported faction navy response");w.AgentsState.Standings[localFaction]=0;
 // Acceleration and save boundaries preserve the same progression clock.
 w.Screen=ViewMode.Station;w.StationId=station.Id;w.SystemId=station.System;DateTime before=w.Now;w.SimulationSpeed=20;w.Update(1);Check(Math.Abs((w.Now-before).TotalSeconds-20)<.0001,"accelerated simulation clock");w.SimulationSpeed=1;
 var lost=w.Player;w.RecoveryStationId=station.Id;w.StationId="";w.SystemId=station.System;w.Screen=ViewMode.Space;w.Player.Hull=0;w.CargoItems["miner"]=3;w.RecoverImported();Check(w.Docked&&w.StationId==station.Id&&!ReferenceEquals(w.Player,lost)&&w.CargoItems.Count==0,"imported ship-loss recovery");
 // Source IDs and save namespaces must never alias an authored station.
 Check(w.ActiveSavePath43!=DemoWorld.SavePath&&w.LocationSystem(station.Id)==station.System,"separate world namespace");
 var oldJson=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(w.ActiveSavePath43))!;oldJson["SaveSchemaVersion"]=45;oldJson.AsObject().Remove("SimulationUtc");oldJson.AsObject().Remove("WalletFunds");string oldBytes=oldJson.ToJsonString();string fixture=Path.Combine(dir,"pass45-imported.json");File.WriteAllText(fixture,oldBytes);var migrated=new DemoWorld();Check(migrated.Load(fixture)&&File.ReadAllText(fixture+".pre-stage-a.bak")==oldBytes,"exact legacy backup");
 Console.WriteLine($"{checks} Stage A integration checks passed.");
 }finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);Directory.Delete(dir,true);}}
}
